// args[0]의 값으로 "%1$tY-%1$tm-%1$te"를 전달하면 시스템에서 가지고 있는 날짜(2014-10-14) 정보가 노출
import java.util.Calendar;
    :
public static void main(String[] args) {
    Calendar validDate = Calendar.getInstance();
    validDate.set(2014, Calendar.OCTOBER, 14);

    if (args.length <= 0) {
        System.out.println("Please Input Date (YYYY-MM-DD) !!!");
        return;
    }
    System.out.printf(
        args[0] + " did not match! HINT: It was issued on %1$terd of some month",
        validDate
    );
