code_examples.safe:
// 외부 입력값이 포맷 문자열 출력에 사용되지 않도록 수정
import java.util.Calendar;
    :
public static void main(String[] args) {
    Calendar validDate = Calendar.getInstance();
    validDate.set(2014, Calendar.OCTOBER, 14);

    if (args.length <= 0) {
        System.out.println("Please Input Date (YYYY-MM-DD) !!!");
        return;
    }
    System.out.printf(
        "%s did not match! HINT: It was issued on %2$terd of some month",
        args[0], validDate
    );
    // Result: %1$te did not match! HINT: It was issued on 14rd of some month
}

